// Clean, Deep Extract Text, and Duplicate Security
const inputData = $input.first().json;

// 1. Helper function to deep scan and find the real string message
function extractRealText(obj) {
    if (!obj) return "";
    if (typeof obj === 'string') return obj;

    // Agar text key ke andar direct body string hai
    if (obj.text && typeof obj.text === 'string') return obj.text;
    if (obj.body && typeof obj.body === 'string') return obj.body;
    if (obj.message && typeof obj.message === 'string') return obj.message;

    // Whatsapp specific nested templates check
    if (obj.text && typeof obj.text === 'object') {
        if (obj.text.body) return obj.text.body;
    }

    // Deep loop inside arrays or objects to find raw message
    for (let key in obj) {
        if (obj.hasOwnProperty(key) && typeof obj[key] === 'object') {
            let nested = extractRealText(obj[key]);
            if (nested && nested !== "[object Object]") return nested;
        } else if (key === 'text' || key === 'body' || key === 'message' || key === 'data') {
            if (obj[key] && typeof obj[key] !== 'object') return String(obj[key]);
        }
    }
    return "";
}

// 2. Execute deep parsing on body or the entire payload
let incomingBody = inputData.body || inputData;
let msgText = extractRealText(incomingBody).trim();

// Fallback logic agar fir bhi text na mile
if (!msgText || msgText === "[object Object]") {
    msgText = inputData.text || (inputData.body ? (inputData.body.text || inputData.body.body || "") : "");
    if (typeof msgText === 'object') msgText = JSON.stringify(msgText);
}
msgText = String(msgText).trim();

// 3. Phone normalization logic
let rawPhone = String(incomingBody.phone || incomingBody.mobile || incomingBody.from || "").replace(/\D/g, '');
const phoneMatch = msgText.match(/\b\d{10}/);
if (rawPhone.length < 10 && phoneMatch) { rawPhone = phoneMatch[0]; }
if (rawPhone.length === 10) rawPhone = "91" + rawPhone;
if (rawPhone.length < 10) rawPhone = "917049869870";

// 4. Customer Name extractor
let customerName = String(incomingBody.senderName || incomingBody.name || incomingBody.pushName || "").trim();
if (!customerName || customerName === "undefined" || customerName === "[object Object]") {
    customerName = "Verified Investor";
}

// 5. DUPLICATE SECURITY ENGINE
let isDuplicateMessage = false;
try {
    const nodeContext = this.getContext('node');
    const lastMessageKey = `last_msg_${rawPhone}`;
    const lastTimestampKey = `last_time_${rawPhone}`;

    const lastMsg = nodeContext[lastMessageKey];
    const lastTime = nodeContext[lastTimestampKey];
    const currentTime = Date.now();

    if (lastMsg === msgText || (lastTime && (currentTime - lastTime < 3000))) {
        isDuplicateMessage = true;
    }

    nodeContext[lastMessageKey] = msgText;
    nodeContext[lastTimestampKey] = currentTime;
} catch (e) {
    isDuplicateMessage = false;
}

return [{ 
  json: { 
    customerName: customerName, 
    customerPhone: rawPhone, 
    rawIncomingMessage: msgText, 
    leadTimestamp: new Date().toISOString(),
    isDuplicate: isDuplicateMessage
  } 
}];

const prevData = $('NORMALIZE_REALESTATE_LEAD').first().json;
const aiRaw = String($input.first()?.json?.response ?? $input.first()?.json?.text ?? '').trim();

// Default values safely setup
let ai = { 
  whatsapp_message: "", 
  final_operation: "GENERAL_INQUIRY", 
  appointment_date: "", 
  appointment_time: "", 
  budget: "", 
  preferredHighway: "", 
  propertyType: "Plot", 
  lead_quality: "WARM" 
};

try {
  const cleaned = aiRaw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  ai = JSON.parse(cleaned);
} catch(e) {
  // Safe user fallback response if JSON parsing errors out
  ai.whatsapp_message = "Dear Investor, Thank you for contacting us. We have received your query regarding Madhu Nag Premium Plots and our Relationship Manager will connect with you shortly. 🏢✨";
}

// Fallback logic check to avoid sending raw JSON formatting to the customer
let dynamicMessage = ai.whatsapp_message || aiRaw;
if (dynamicMessage.startsWith('{') && ai.whatsapp_message === "") {
    dynamicMessage = "Dear Investor, Thank you for your interest in Madhu Nag Premium Plots. Our team is processing your request on priority. 🏢✨";
}

return [{ 
  json: { 
    ...prevData, 
    finalMessage: dynamicMessage, 
    final_operation: ai.final_operation || "GENERAL_INQUIRY", 
    appointment_date: ai.appointment_date || "", 
    appointment_time: ai.appointment_time || "", 
    budget: ai.budget || "", 
    preferredHighway: ai.preferredHighway || "", 
    propertyType: ai.propertyType || "Plot", 
    leadQuality: ai.lead_quality || "WARM",      // Maps perfectly to {{ $json.leadQuality }}
    lead_quality: ai.lead_quality || "WARM",     // Maps perfectly to {{ $json.lead_quality }}
    shouldSendStr: "true" 
  } 
}];

